/* SPK reader: every supported segment type, chains of segments and priorities, against
 * states evaluated by CSPICE N0067 (tests/data/spk/reference.txt, generated by spkw*_c writers
 * and spkgeo_c; eros.bsp is a type 21 file from JPL Horizons); errors and atomic loading. */
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "core/fpguard.h"
#include "mtest.h"
#include "myb/io.h"
#include "myb/kin.h"

#define SPK_DIR MYB_TEST_DATA_DIR "/spk/"

typedef struct type_stats {
  int type;
  long count;
  double position; /* max |error| / |r| */
  double velocity; /* max |error| / |v| */
} type_stats;

static type_stats stats[32];
static int stats_count;

static type_stats* stats_for(int type) {
  for (int i = 0; i < stats_count; ++i) {
    if (stats[i].type == type) {
      return &stats[i];
    }
  }
  stats[stats_count] = (type_stats){type, 0, 0.0, 0.0};
  return &stats[stats_count++];
}

static double norm3(const double* v) {
  return sqrt(v[0] * v[0] + v[1] * v[1] + v[2] * v[2]);
}

/* Parses the next whitespace-separated number of a line. */
static int next_number(const char** p, double* value) {
  /* bound: skips at most the rest of the line */
  while (**p == ' ' || **p == '\t') {
    ++*p;
  }
  size_t used = 0;
  if (myb_parse_double(*p, strlen(*p), value, &used) != MYB_OK) {
    return 0;
  }
  *p += used;
  return 1;
}

static myb_spk* open_set(const char* files) {
  myb_spk* spk = NULL;
  MT_CHECK(myb_spk_create(NULL, &spk) == MYB_OK);
  char list[256];
  snprintf(list, sizeof list, "%s", files);
  char* rest = list;
  /* bound: one file per '+'-separated name */
  for (char* name = strtok(rest, "+"); name != NULL; name = strtok(NULL, "+")) {
    char path[512];
    snprintf(path, sizeof path, "%s%s", SPK_DIR, name);
    myb_diag diag;
    const myb_status status = myb_spk_load_file(spk, path, &diag);
    if (status != MYB_OK) {
      fprintf(stderr, "load %s: %s (%s)\n", path, myb_status_name(status), diag.message);
    }
    MT_CHECK(status == MYB_OK);
  }
  return spk;
}

/* Type of the segment that serves (target, center) in a file set, for the statistics. */
static int type_of(const myb_spk* spk, int target) {
  int type = 0;
  for (size_t i = 0; i < myb_spk_segment_count(spk); ++i) {
    myb_spk_segment_info info;
    myb_spk_segment(spk, i, &info);
    if (info.target == target) {
      type = info.type;
    }
  }
  return type;
}

static void test_reference(void) {
  FILE* f = fopen(SPK_DIR "reference.txt", "r");
  MT_CHECK(f != NULL);
  if (f == NULL) {
    return;
  }
  char line[1024];
  char current[256] = "";
  myb_spk* spk = NULL;
  long lines = 0;
  /* bound: one iteration per line of the file */
  while (fgets(line, sizeof line, f) != NULL) {
    if (line[0] == '#') {
      continue;
    }
    char files[256];
    int target = 0;
    int center = 0;
    int consumed = 0;
    if (sscanf(line, "%255s %d %d%n", files, &target, &center, &consumed) != 3) {
      continue;
    }
    if (strcmp(files, current) != 0) {
      myb_spk_destroy(spk);
      spk = open_set(files);
      snprintf(current, sizeof current, "%s", files);
    }
    const char* p = line + consumed;
    double et = 0.0;
    double expected[6];
    int ok = next_number(&p, &et);
    for (int i = 0; i < 6; ++i) {
      ok = ok && next_number(&p, &expected[i]);
    }
    MT_CHECK(ok);
    double state[6];
    int32_t frame = -1;
    const myb_status status =
        myb_spk_state(spk, target, center, myb_time_from_seconds(et), state, &frame);
    if (status != MYB_OK) {
      fprintf(stderr, "%s %d %d %.17g: %s\n", files, target, center, et,
                       myb_status_name(status));
    }
    MT_CHECK(status == MYB_OK && frame == 1);
    double dr[3];
    double dv[3];
    for (int i = 0; i < 3; ++i) {
      dr[i] = state[i] / 1000.0 - expected[i];
      dv[i] = state[i + 3] / 1000.0 - expected[i + 3];
    }
    const int type = strchr(files, '+') != NULL ? 100 : type_of(spk, target);
    type_stats* s = stats_for(type);
    const double ep = norm3(dr) / norm3(expected);
    const double ev = norm3(dv) / norm3(expected + 3);
    s->count++;
    if (ep > s->position) {
      s->position = ep;
    }
    if (ev > s->velocity) {
      s->velocity = ev;
    }
    ++lines;
  }
  fclose(f);
  myb_spk_destroy(spk);
  MT_CHECK(lines > 6000);
  for (int i = 0; i < stats_count; ++i) {
    const type_stats* s = &stats[i];
    printf("type %3d (100 = chains): %5ld states, max relative error r %.2e, v %.2e\n", s->type,
           s->count, s->position, s->velocity);
    /* Measured (Windows, Clang 23): <= 6.3e-16 for positions of every type, and for velocities
     * except Hermite (types 12, 13, 19: 1.1e-14) and type 17 (7.6e-15). The Hermite difference
     * is CSPICE's: against a 300-bit evaluation of the interpolant, myb's velocities are off by
     * <= 1.6e-16 and CSPICE's by up to 2.3e-14 (its interpolation works on absolute epochs).
     * Type 17 differentiates an equivalent expression of its own; type 5 solves Kepler's
     * equation with an independent solver. */
    const double limit = (s->type == 5 || s->type == 17) ? 5e-14 : 3e-14;
    MT_CHECK(s->position < (s->type == 17 ? 2e-14 : 2e-15) && s->velocity < limit);
  }
}

static void test_errors(void) {
  myb_spk* spk = NULL;
  MT_CHECK(myb_spk_create(NULL, &spk) == MYB_OK);
  myb_diag diag;
  MT_CHECK(myb_spk_load_file(spk, SPK_DIR "missing.bsp", &diag) == MYB_E_IO);
  MT_CHECK(myb_spk_load_file(spk, SPK_DIR "reference.txt", &diag) == MYB_E_FORMAT);
  MT_CHECK(myb_spk_segment_count(spk) == 0);
  double state[6];
  MT_CHECK(myb_spk_state(spk, 1, 2, myb_time_from_seconds(0.0), state, NULL) == MYB_E_RANGE);
  MT_CHECK(myb_spk_state(spk, 5, 5, myb_time_from_seconds(0.0), state, NULL) == MYB_OK);
  MT_CHECK(state[0] == 0.0 && state[5] == 0.0);

  /* A damaged image: loading fails and leaves the set unchanged. */
  FILE* f = fopen(SPK_DIR "t02_03.bsp", "rb");
  MT_CHECK(f != NULL);
  static unsigned char image[16384];
  const size_t size = f != NULL ? fread(image, 1, sizeof image, f) : 0;
  if (f != NULL) {
    fclose(f);
  }
  MT_CHECK(size == 10240);
  MT_CHECK(myb_spk_load_memory(spk, image, size, &diag) == MYB_OK);
  MT_CHECK(myb_spk_segment_count(spk) == 2);
  myb_spk_segment_info info;
  myb_spk_segment(spk, 0, &info);
  MT_CHECK(info.target == 1002 && info.center == 399 && info.type == 2 && info.frame == 1);
  MT_CHECK(strcmp(info.name, "type 2") == 0 && info.file == 0);
  static unsigned char broken[16384];
  memcpy(broken, image, size);
  broken[700] = '\n'; /* the FTP validation string */
  MT_CHECK(myb_spk_load_memory(spk, broken, size, &diag) == MYB_E_FORMAT);
  MT_CHECK(strstr(diag.message, "text-mode") != NULL);
  memcpy(broken, image, size);
  memcpy(broken + 88, "VAX-GFLT", 8);
  MT_CHECK(myb_spk_load_memory(spk, broken, size, &diag) == MYB_E_FORMAT);
  MT_CHECK(myb_spk_segment_count(spk) == 2);
  /* Outside the coverage, and a body without data. */
  MT_CHECK(myb_spk_state(spk, 1002, 399, myb_time_from_seconds(6.9e8), state, NULL) ==
           MYB_E_RANGE);
  MT_CHECK(myb_spk_state(spk, 1002, 10, myb_time_from_seconds(7.0e8 + 10.0), state, NULL) ==
           MYB_E_RANGE);
  /* Through the common center 399: 1002 relative to 1003. */
  double a[6];
  double b[6];
  const myb_time t = myb_time_from_seconds(7.0e8 + 12345.678);
  MT_CHECK(myb_spk_state(spk, 1002, 399, t, a, NULL) == MYB_OK);
  MT_CHECK(myb_spk_state(spk, 1003, 399, t, b, NULL) == MYB_OK);
  MT_CHECK(myb_spk_state(spk, 1002, 1003, t, state, NULL) == MYB_OK);
  for (int i = 0; i < 6; ++i) {
    MT_CHECK(fabs(state[i] - (a[i] - b[i])) <= 1e-15 * fabs(a[i] - b[i]) + 1e-9);
  }
  /* The reversed pair is the exact negative. */
  double reversed[6];
  MT_CHECK(myb_spk_state(spk, 1003, 1002, t, reversed, NULL) == MYB_OK);
  for (int i = 0; i < 6; ++i) {
    MT_CHECK(reversed[i] == -state[i]);
  }
  myb_spk_destroy(spk);
  myb_spk_destroy(NULL);
}

/* The type 21 file from Horizons against the vectors Horizons itself prints for the same
 * solution (tests/data/spk/eros_horizons.txt). */
static void test_horizons(void) {
  myb_spk* spk = open_set("eros.bsp");
  FILE* f = fopen(SPK_DIR "eros_horizons.txt", "r");
  MT_CHECK(f != NULL);
  if (f == NULL) {
    myb_spk_destroy(spk);
    return;
  }
  char line[512];
  int rows = 0;
  double worst = 0.0;
  /* bound: one iteration per line of the file */
  while (fgets(line, sizeof line, f) != NULL) {
    if (line[0] == '#') {
      continue;
    }
    const char* p = line;
    double jd = 0.0;
    size_t used = 0;
    MT_CHECK(myb_parse_double(p, strlen(p), &jd, &used) == MYB_OK);
    p = strchr(p + used + 1, ','); /* skip the calendar label */
    MT_CHECK(p != NULL);
    if (p == NULL) {
      break;
    }
    double expected[6];
    for (int i = 0; i < 6; ++i) {
      ++p; /* the comma */
      MT_CHECK(next_number(&p, &expected[i]));
    }
    double state[6];
    MT_CHECK(myb_spk_state(spk, 20000433, 10, myb_time_from_jd(jd, 0.0), state, NULL) == MYB_OK);
    double dr[3];
    double dv[3];
    for (int i = 0; i < 3; ++i) {
      dr[i] = state[i] / 1000.0 - expected[i];
      dv[i] = state[i + 3] / 1000.0 - expected[i + 3];
    }
    worst = fmax(worst, fmax(norm3(dr) / norm3(expected), norm3(dv) / norm3(expected + 3)));
    ++rows;
  }
  fclose(f);
  myb_spk_destroy(spk);
  printf("Horizons vectors of 433 Eros: %d dates, max relative difference %.2e\n", rows, worst);
  /* Horizons prints its own integration, not the difference lines it exports: CSPICE's
   * evaluation of eros.bsp differs from these vectors by the same amount as myb's (up to
   * 1.7e-12 relative, 0.3 m, growing from the start of the file), while myb and CSPICE agree to
   * 2e-16 (test_reference). */
  MT_CHECK(rows == 8 && worst < 5e-12);
}

int main(void) {
  test_reference();
  test_horizons();
  test_errors();
  return mt_finish("test_spk");
}
